/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][10]=[{"key":"l11079:2","law":"l11079","ref":"2","label":"Lei das Parcerias Público-Privadas · Art. 2","paragraphs":["Art. 2º Parceria público-privada é o contrato administrativo de concessão, na modalidade patrocinada ou administrativa.","§ 1º Concessão patrocinada é a concessão de serviços públicos ou de obras públicas de que trata a Lei nº 8.987, de 13 de fevereiro de 1995, quando envolver, adicionalmente à tarifa cobrada dos usuários contraprestação pecuniária do parceiro público ao parceiro privado.","§ 2º Concessão administrativa é o contrato de prestação de serviços de que a Administração Pública seja a usuária direta ou indireta, ainda que envolva execução de obra ou fornecimento e instalação de bens.","§ 3º Não constitui parceria público-privada a concessão comum, assim entendida a concessão de serviços públicos ou de obras públicas de que trata a Lei nº 8.987, de 13 de fevereiro de 1995, quando não envolver contraprestação pecuniária do parceiro público ao parceiro privado.","§ 4º É vedada a celebração de contrato de parceria público-privada:","I - cujo valor do contrato seja inferior a R$ 10.000.000,00 (dez milhões de reais); (Inciso com redação dada pela Lei nº 13.529, de 4/12/2017)","II - cujo período de prestação do serviço seja inferior a 5 (cinco) anos; ou","III - que tenha como objeto único o fornecimento de mão-de-obra, o fornecimento e instalação de equipamentos ou a execução de obra pública.","§ 5º (VETADO na Lei nº 12.619, de 30/4/2012)"],"url":""},{"key":"l11079:4","law":"l11079","ref":"4","label":"Lei das Parcerias Público-Privadas · Art. 4","paragraphs":["Art. 4º Na contratação de parceria público-privada serão observadas as seguintes diretrizes:","I - eficiência no cumprimento das missões de Estado e no emprego dos recursos da sociedade;","II - respeito aos interesses e direitos dos destinatários dos serviços e dos entes privados incumbidos da sua execução;","III - indelegabilidade das funções de regulação, jurisdicional, do exercício do poder de polícia e de outras atividades exclusivas do Estado;","IV - responsabilidade fiscal na celebração e execução das parcerias;","V - transparência dos procedimentos e das decisões;","VI - repartição objetiva de riscos entre as partes;","VII - sustentabilidade financeira e vantagens socioeconômicas dos projetos de parceria."],"url":""},{"key":"l11079:3","law":"l11079","ref":"3","label":"Lei das Parcerias Público-Privadas · Art. 3","paragraphs":["Art. 3º As concessões administrativas regem-se por esta Lei, aplicando-se-lhes adicionalmente o disposto nos arts. 21, 23, 25 e 27 a 39 da Lei nº 8.987, de 13 de fevereiro de 1995, e no art. 31 da Lei nº 9.074, de 7 de julho de 1995.","§ 1º As concessões patrocinadas regem-se por esta Lei, aplicando-se-lhes subsidiariamente o disposto na Lei nº 8.987, de 13 de fevereiro de 1995, e nas leis que lhe são correlatas.","§ 2º As concessões comuns continuam regidas pela Lei nº 8.987, de 13 de fevereiro de 1995, e pelas leis que lhe são correlatas, não se lhes aplicando o disposto nesta Lei.","§ 3º Continuam regidos exclusivamente pela Lei nº 8.666, de 21 de junho de 1993, e pelas leis que lhe são correlatas os contratos administrativos que não caracterizem concessão comum, patrocinada ou administrativa."],"url":""},{"key":"l11079:6","law":"l11079","ref":"6","label":"Lei das Parcerias Público-Privadas · Art. 6","paragraphs":["Art. 6º A contraprestação da Administração Pública nos contratos de parceria público-privada poderá ser feita por:","I - ordem bancária;","II - cessão de créditos não tributários;","III - outorga de direitos em face da Administração Pública;","IV - outorga de direitos sobre bens públicos dominicais;","V - outros meios admitidos em lei.","§ 1º O contrato poderá prever o pagamento ao parceiro privado de remuneração variável vinculada ao seu desempenho, conforme metas e padrões de qualidade e disponibilidade definidos no contrato. (Parágrafo único transformado em § 1º com redação dada pela Medida Provisória nº 575, de 7/8/201 2, convertida na Lei nº 12.766, de 27/12/2012 )","§ 2º O contrato poderá prever o aporte de recursos em favor do parceiro privado para a realização de obras e aquisição de bens reversíveis, nos termos dos incisos X e XI do caput do art. 18 da Lei no 8.987, de 13 de fevereiro de 1995, desde que autorizado no edital de licitação, se contratos novos, ou em lei específica, se contratos celebrados até 8 de agosto de 2012. (Parágrafo com redação dada pela Lei nº 12.766, de 27/12/2012 )","§ 3º O valor do aporte de recursos realizado nos termos do § 2º poderá ser excluído da determinação:","I - do lucro líquido para fins de apuração do lucro real e da base de cálculo da Contribuição Social sobre o Lucro Líquido - CSLL; e","II - da base de cálculo da Contribuição para o PIS/P asep e da Contribuição para o Financiamento da Seguridade Social - COFINS . (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","III - da base de cálculo da Contribuição Previdenciária sobre a Receita Bruta - CPRB devida pelas empresas referidas nos arts. 7 º e 8 º da Lei n º 12.546, de 14 de dezembro de 2011, a partir de 1 º de janeiro de 2015. ( Inciso acrescido pela Lei nº 13.043, de 13/11/2014)","§ 4º Até 31 de dezembro de 2013, para os optantes conforme o art. 75 da Lei n º 12.973, de 13 de maio de 2014, e até 31 de dezembro de 2014, para os não optantes, a parcela excluída nos termos do § 3 º deverá ser computada na determinação do lucro líquido para fins de apuração do lucro real, da base de cálculo da CSLL e da base de cálculo da Contribuição para o PIS/Pasep e da Cofins, na proporção em que o custo para a realização de obras e aquisição de bens a que se refere o § 2 º deste artigo for realizado, inclusive mediante depreciação ou extinção da concessão, nos termos do art. 35 da Lei n º 8.987, de 13 de fevereiro de 1995 . (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , e com redação dada pela Lei nº 13.043, de 13/11/2014)","§ 5 º Por ocasião da extinção do contrato, o parceiro privado não receberá indenização pelas parcelas de investimentos vinculados a bens reversíveis ainda não amortizadas ou depreciadas, quando tais investimentos houverem sido realizados com valores provenientes do aporte de recursos de que trata o § 2 º. ( Parágrafo acrescido pela Lei nº 12.766, de 27/12/2012)","§ 6º A partir de 1º de janeiro de 2014, para os optantes conforme o art. 75 da Lei n º 12.973, de 13 de maio de 2014, e de 1 º de janeiro de 2015, para os não optantes, a parcela excluída nos termos do § 3 º deverá ser computada na determinação do lucro líquido para fins de apuração do lucro real, da base de cálculo da CSLL e da base de cálculo da Contribuição para o PIS/Pasep e da Cofins em cada período de apuração durante o prazo restante do contrato, considerado a partir do início da prestação dos serviços públicos. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)","§ 7º No caso do § 6 º , o valor a ser adicionado em cada período de apuração deve ser o valor da parcela excluída dividida pela quantidade de períodos de apuração contidos no prazo restante do contrato. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)","§ 8º Para os contratos de concessão em que a concessionária já tenha iniciado a prestação dos serviços públicos nas datas referidas no § 6º , as adições subsequentes serão realizadas em cada período de apuração durante o prazo restante do contrato, considerando o saldo remanescente ainda não adicionado. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)","§ 9º A parcela excluída nos termos do inciso III do § 3º deverá ser computada na determinação da base de cálculo da contribuição previdenciária de que trata o inciso III do § 3 º em cada período de apuração durante o prazo restante previsto no contrato para construção, recuperação, reforma, ampliação ou melhoramento da infraestrutura que será utilizada na prestação de serviços públicos. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)","§ 10. No caso do § 9 º , o valor a ser adicionado em cada período de apuração deve ser o valor da parcela excluída dividida pela quantidade de períodos de apuração contidos no prazo restante previsto no contrato para construção, recuperação, reforma, ampliação ou melhoramento da infraestrutura que será utilizada na prestação de serviços públicos. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)","§ 11. Ocorrendo a extinção da concessão antes do advento do termo contratual, o saldo da par cela excluída nos termos do § 3º , ainda não adicionado, deverá ser computado na determinação do lucro líquido para fins de apuração do lucro real, da base de cálculo da CSLL e da base de cálculo da Contribuição para o PIS/Pasep, da Cofins e da contribuição previdenciária de que trata o inciso III do § 3 º no período de apuração da extinção. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)","§ 12. Aplicam-se às receitas auferidas pelo parceiro privado nos termos do § 6º o regime de apuração e as alíquotas da Contribuição para o PIS/Pasep e da Cofins aplicáveis às suas receitas decorrentes da p restação dos serviços públicos. ( Parágrafo acrescido pela Lei nº 13.043, de 13/11/2014)"],"url":""},{"key":"l11079:10","law":"l11079","ref":"10","label":"Lei das Parcerias Público-Privadas · Art. 10","paragraphs":["Art. 10. A contratação de parceria público-privada será precedida de licitação na modalidade concorrência ou diálogo competitivo, estando a abertura do processo licitatório condicionada a : ( “Caput” do artigo com redação dada pela Lei nº 14.133, de 1º/4/2021)","I - autorização da autoridade competente, fundamentada em estudo técnico que demonstre:","a) a conveniência e a oportunidade da contratação, mediante identificação das razões que justifiquem a opção pela forma de parceria público-privada;","b) que as despesas criadas ou aumentadas não afetarão as metas de resultados fiscais previstas no Anexo referido no § 1º do art. 4º da Lei Complementar nº 101, de 4 de maio de 2000, devendo seus efeitos financeiros, nos períodos seguintes, ser compensados pelo aumento permanente de receita ou pela redução permanente de despesa; e","c) quando for o caso, conforme as normas editadas na forma do art. 25 desta Lei, a observância dos limites e condições decorrentes da aplicação dos arts. 29, 30 e 32 da Lei Complementar nº 101, de 4 de maio de 2000, pelas obrigações contraídas pela Administração Pública relativas ao objeto do contrato;","II - elaboração de estimativa do impacto orçamentário-financeiro nos exercícios em que deva vigorar o contrato de parceria público-privada;","III - declaração do ordenador da despesa de que as obrigações contraídas pela Administração Pública no decorrer do contrato são compatíveis com a lei de diretrizes orçamentárias e estão previstas na lei orçamentária anual;","IV - estimativa do fluxo de recursos públicos suficientes para o cumprimento, durante a vigência do contrato e por exercício financeiro, das obrigações contraídas pela Administração Pública;","V - seu objeto estar previsto no plano plurianual em vigor no âmbito onde o contrato será celebrado;","VI - submissão da minuta de edital e de contrato à consulta pública, mediante publicação na imprensa oficial, em jornais de grande circulação e por meio eletrônico, que deverá informar a justificativa para a contratação, a identificação do objeto, o prazo de duração do contrato, seu valor estimado, fixando-se prazo mínimo de 30 (trinta) dias para recebimento de sugestões, cujo termo dar-se-á pelo menos 7 (sete) dias antes da data prevista para a publicação do edital; e","VII - licença ambiental prévia ou expedição das diretrizes para o licenciamento ambiental do empreendimento, na forma do regulamento, sempre que o objeto do contrato exigir.","§ 1º A comprovação referida nas alíneas b e c do inciso I do caput deste artigo conterá as premissas e metodologia de cálculo utilizadas, observadas as normas gerais para consolidação das contas públicas, sem prejuízo do exame de compatibilidade das despesas com as demais normas do plano plurianual e da lei de diretrizes orçamentárias.","§ 2º Sempre que a assinatura do contrato ocorrer em exercício diverso daquele em que for publicado o edital, deverá ser precedida da atualização dos estudos e demonstrações a que se referem os incisos I a IV do caput deste artigo.","§ 3º As concessões patrocinadas em que mais de 70% (setenta por cento) da remuneração do parceiro privado for paga pela Administração Pública dependerão de autorização legislativa específica.","§ 4 º Os estudos de engenharia para a definição do valor do investimento da PPP deverão ter nível de detalhamento de anteprojeto, e o valor dos investimentos para definição do preço de referência para a licitação será calculado com base em valores de mercado considerando o custo global de obras semelhantes no Brasil ou no exterior ou com base em sistemas de custos que utilizem como insumo valores de mercado do setor específico do projeto, aferidos, em qualquer caso, mediante orçamento sintético, elaborado por meio de metod ologia expedita ou paramétrica. (Parágrafo acrescido pela Lei nº 12.766, de 27/12/2012)"],"url":""},{"key":"l8987:3","law":"l8987","ref":"3","label":"Lei de Concessões e Permissões · Art. 3","paragraphs":["Art. 3º As concessões e permissões sujeitar-se-ão à fiscalização pelo poder concedente responsável pela delegação, com a cooperação dos usuários."],"url":""},{"key":"l8987:21","law":"l8987","ref":"21","label":"Lei de Concessões e Permissões · Art. 21","paragraphs":["Art. 21. Os estudos, investigações, levantamentos, projetos, obras e despesas ou investimentos já efetuados, vinculados à concessão, de utilidade para a licitação, realizados pelo poder concedente ou com a sua autorização, estarão à disposição dos interessados, devendo o vencedor da licitação ressarcir os dispêndios correspondentes, especificados no edital."],"url":""},{"key":"l8987:23","law":"l8987","ref":"23","label":"Lei de Concessões e Permissões · Art. 23","paragraphs":["Art. 23. São cláusulas essenciais do contrato de concessão as relativas:","I - ao objeto, à área e ao prazo da concessão;","II - ao modo, forma e condições de prestação do serviço;","III - aos critérios, indicadores, fórmulas e parâmetros definidores da qualidade do serviço;","IV - ao preço do serviço e aos critérios e procedimentos para o reajuste e a revisão das tarifas;","V - aos direitos, garantias e obrigações do poder concedente e da concessionária, inclusive os relacionados às previsíveis necessidades de futura alteração e expansão do serviço e conseqüente modernização, aperfeiçoamento e ampliação dos equipamentos e das instalações;","VI - aos direitos e deveres dos usuários para obtenção e utilização do serviço;","VII - à forma de fiscalização das instalações, dos equipamentos, dos métodos e práticas de execução do serviço, bem como a indicação dos órgãos competentes para exercê-la;","VIII - às penalidades contratuais e administrativas a que se sujeita a concessionária e sua forma de aplicação;","IX - aos casos de extinção da concessão;","X - aos bens reversíveis;","XI - aos critérios para o cálculo e a forma de pagamento das indenizações devidas à concessionária, quando for o caso;","XII - às condições para prorrogação do contrato;","XIII - à obrigatoriedade, forma e periodicidade da prestação de contas da concessionária ao poder concedente;","XIV - à exigência da publicação de demonstrações financeiras periódicas da concessionária; e","XV - ao foro e ao modo amigável de solução das divergências contratuais.","XVI - (VETADO na Lei nº 13.448, de 5/6/2017)","Parágrafo único. Os contratos relativos à concessão de serviço público precedido da execução de obra pública deverão, adicionalmente:","I - estipular os cronogramas físico-financeiros de execução das obras vinculadas à concessão; e","II - exigir garantia do fiel cumprimento, pela concessionária, das obrigações relativas às obras vinculadas à concessão."],"url":""},{"key":"l8987:25","law":"l8987","ref":"25","label":"Lei de Concessões e Permissões · Art. 25","paragraphs":["Art. 25. Incumbe à concessionária a execução do serviço concedido, cabendo-lhe responder por todos os prejuízos causados ao poder concedente, aos usuários ou a terceiros, sem que a fiscalização exercida pelo órgão competente exclua ou atenue essa responsabilidade.","§ 1º Sem prejuízo da responsabilidade a que se refere este artigo, a concessionária poderá contratar com terceiros o desenvolvimento de atividades inerentes, acessórias ou complementares ao serviço concedido, bem como a implementação de projetos associados.","§ 2º Os contratos celebrados entre a concessionária e os terceiros a que se refere o parágrafo anterior reger-se-ão pelo direito privado, não se estabelecendo qualquer relação jurídica entre os terceiros e o poder concedente.","§ 3º A execução das atividades contratadas com terceiros pressupõe o cumprimento das normas regulamentares da modalidade do serviço concedido."],"url":""},{"key":"l8987:27","law":"l8987","ref":"27","label":"Lei de Concessões e Permissões · Art. 27","paragraphs":["Art. 27. A transferência de concessão ou do controle societário da concessionária sem prévia anuência do poder concedente implicará a caducidade da concessão.","§ 1º Para fins de obtenção da anuência de que trata o caput deste artigo, o pretendente deverá:","I - atender às exigências de capacidade técnica, idoneidade financeira e regularidade jurídica e fiscal necessárias à assunção do serviço; e","II - comprometer-se a cumprir todas as cláusulas do contrato em vigor. (Parágrafo único transformado em § 1 º pela Lei nº 11.196, de 21/11/2005)","§ 2º (Parágrafo acrescido pela Lei nº 11.196, de 21/11/2005 e revogado pela Lei nº 13.097, de 19/1/2015)","§ 3º (Parágrafo acrescido pela Lei nº 11.196, de 21/11/2005 e revogado pela Lei nº 13.097, de 19/1/2015)","§ 4º (Parágrafo acrescido pela Lei nº 11.196, de 21/11/2005 e revogado pela Lei nº 13.097, de 19/1/2015)"],"url":""},{"key":"l8987:39","law":"l8987","ref":"39","label":"Lei de Concessões e Permissões · Art. 39","paragraphs":["Art. 39. O contrato de concessão poderá ser rescindido por iniciativa da concessionária, no caso de descumprimento das normas contratuais pelo poder concedente, mediante ação judicial especialmente intentada para esse fim.","Parágrafo único. Na hipótese prevista no caput deste artigo, os serviços prestados pela concessionária não poderão ser interrompidos ou paralisados, até a decisão judicial transitada em julgado."],"url":""},{"key":"l8987:27-A","law":"l8987","ref":"27-A","label":"Lei de Concessões e Permissões · Art. 27-A","paragraphs":["Art. 27-A. Nas condições estabelecidas no contrato de concessão, o poder concedente autorizará a assunção do controle ou da administração temporária da concessionária por seus financiadores e garantidores com quem não mantenha vínculo societário direto, para promover sua reestruturação financeira e assegurar a continuidade da prestação dos serviços.","§ 1 º Na hipótese prevista no caput , o poder concedente exigirá dos financiadores e dos garantidores que atendam às exigências de regularidade jurídica e fiscal, podendo alterar ou dispensar os demais requisitos previstos no inciso I do parágrafo único do art. 27.","§ 2 º A assunção do controle ou da administração temporária autorizadas na forma do caput deste artigo não alterará as obrigações da concessionária e de seus controladores para com terceiros, poder concedente e usuários dos serviços públicos.","§ 3 º Configura-se o controle da concessionária, para os fins dispostos no caput deste artigo, a propriedade resolúvel de ações ou quotas por seus financiadores e garantidores que atendam os requisitos do art. 116 da Lei no 6.404, de 15 de dezembro de 1976.","§ 4 º Configura-se a administração temporária da concessionária por seus financiadores e garantidores quando, sem a transferência da propriedade de ações ou quotas, forem outorgados os seguintes poderes:","I - indicar os membros do Conselho de Administração, a serem eleitos em Assembleia Geral pelos acionistas, nas sociedades regidas pela Lei 6.404, de 15 de dezembro de 1976; ou administradores, a serem eleitos pelos quotistas, nas demais sociedades;","II - indicar os membros do Conselho Fiscal, a serem eleitos pelos acionistas ou quotistas controladores em Assembleia Geral;","III - exercer poder de veto sobre qualquer proposta submetida à votação dos acionistas ou quotistas da concessionária, que representem, ou possam representar, prejuízos aos fins previstos no caput deste artigo;","IV - outros poderes necessários ao alcance dos fins previstos no caput deste artigo.","§ 5 º A administração temporária autorizada na forma deste artigo não acarretará responsabilidade aos financiadores e garantidores em relação à tributação, encargos, ônus, sanções, obrigações ou compromissos com terceiros, inclusive com o poder concedente ou empregados.","§ 6 º O Poder Concedente disciplinará sobre o prazo da administração temporária. (Artigo acrescido pela Lei nº 13.097, de 19/1/2015)"],"url":""},{"key":"l8987:28","law":"l8987","ref":"28","label":"Lei de Concessões e Permissões · Art. 28","paragraphs":["Art. 28. Nos contratos de financiamento, as concessionárias poderão oferecer em garantia os direitos emergentes da concessão, até o limite que não comprometa a operacionalização e a continuidade da prestação do serviço.","Parágrafo único. (Revogado pela Lei nº 9.074, de 7/7/1995)"],"url":""},{"key":"l8987:28-A","law":"l8987","ref":"28-A","label":"Lei de Concessões e Permissões · Art. 28-A","paragraphs":["Art. 28-A. Para garantir contratos de mútuo de longo prazo, destinados a investimentos relacionados a contratos de concessão, em qualquer de suas modalidades, as concessionárias poderão ceder ao mutuante, em caráter fiduciário, parcela de seus créditos operacionais futuros, observadas as seguintes condições:","I - o contrato de cessão dos créditos deverá ser registrado em Cartório de Títulos e Documentos para ter eficácia perante terceiros;","II - sem prejuízo do disposto no inciso I do caput deste artigo, a cessão do crédito não terá eficácia em relação ao Poder Público concedente senão quando for este formalmente notificado;","III - os créditos futuros cedidos nos termos deste artigo serão constituídos sob a titularidade do mutuante, independentemente de qualquer formalidade adicional;","IV - o mutuante poderá indicar instituição financeira para efetuar a cobrança e receber os pagamentos dos créditos cedidos ou permitir que a concessionária o faça, na qualidade de representante e depositária;","V - na hipótese de ter sido indicada instituição financeira, conforme previsto no inciso IV do caput deste artigo, fica a concessionária obrigada a apresentar a essa os créditos para cobrança;","VI - os pagamentos dos créditos cedidos deverão ser depositados pela concessionária ou pela instituição encarregada da cobrança em conta corrente bancária vinculada ao contrato de mútuo;","VII - a instituição financeira depositária deverá transferir os valores recebidos ao mutuante à medida que as obrigações do contrato de mútuo tornarem-se exigíveis; e","VIII - o contrato de cessão disporá sobre a devolução à concessionária dos recursos excedentes, sendo vedada a retenção do saldo após o adimplemento integral do contrato.","Parágrafo único. Para os fins deste artigo, serão considerados contratos de longo prazo aqueles cujas obrigações tenham prazo médio de vencimento superior a 5 (cinco) anos. (Artigo acrescido pela Lei nº 11.196, de 21/11/2005)"],"url":""},{"key":"l8987:29","law":"l8987","ref":"29","label":"Lei de Concessões e Permissões · Art. 29","paragraphs":["Art. 29. Incumbe ao poder concedente:","I - regulamentar o serviço concedido e fiscalizar permanentemente a sua prestação;","II - aplicar as penalidades regulamentares e contratuais;","III - intervir na prestação do serviço, nos casos e condições previstos em lei;","IV - extinguir a concessão, nos casos previstos nesta Lei e na forma prevista no contrato;","V - homologar reajustes e proceder à revisão das tarifas na forma desta Lei, das normas pertinentes e do contrato;","VI - cumprir e fazer cumprir as disposições regulamentares do serviço e as cláusulas contratuais da concessão;","VII - zelar pela boa qualidade do serviço, receber, apurar e solucionar queixas e reclamações dos usuários, que serão cientificados, em até trinta dias, das providências tomadas;","VIII - declarar de utilidade pública os bens necessários à execução do serviço ou obra pública, promovendo as desapropriações, diretamente ou mediante outorga de poderes à concessionária, caso em que será desta a responsabilidade pelas indenizações cabíveis;","IX - declarar de necessidade ou utilidade pública, para fins de instituição de servidão administrativa, os bens necessários à execução de serviço ou obra pública, promovendo-a diretamente ou mediante outorga de poderes à concessionária, caso em que será desta a responsabilidade pelas indenizações cabíveis;","X - estimular o aumento da qualidade, produtividade, preservação do meio-ambiente e conservação;","XI - incentivar a competitividade; e","XII - estimular a formação de associações de usuários para defesa de interesses relativos ao serviço."],"url":""},{"key":"l8987:30","law":"l8987","ref":"30","label":"Lei de Concessões e Permissões · Art. 30","paragraphs":["Art. 30. No exercício da fiscalização, o poder concedente terá acesso aos dados relativos à administração, contabilidade, recursos técnicos, econômicos e financeiros da concessionária.","Parágrafo único. A fiscalização do serviço será feita por intermédio de órgão técnico do poder concedente ou por entidade com ele conveniada, e, periodicamente, conforme previsto em norma regulamentar, por comissão composta de representantes do poder concedente, da concessionária e dos usuários."],"url":""},{"key":"l8987:31","law":"l8987","ref":"31","label":"Lei de Concessões e Permissões · Art. 31","paragraphs":["Art. 31. Incumbe à concessionária:","I - prestar serviço adequado, na forma prevista nesta Lei, nas normas técnicas aplicáveis e no contrato;","II - manter em dia o inventário e o registro dos bens vinculados à concessão;","III - prestar contas da gestão do serviço ao poder concedente e aos usuários, nos termos definidos no contrato;","IV - cumprir e fazer cumprir as normas do serviço e as cláusulas contratuais da concessão;","V - permitir aos encarregados da fiscalização livre acesso, em qualquer época, às obras, aos equipamentos e às instalações integrantes do serviço, bem como a seus registros contábeis;","VI - promover as desapropriações e constituir servidões autorizadas pelo poder concedente, conforme previsto no edital e no contrato;","VII - zelar pela integridade dos bens vinculados à prestação do serviço, bem como segurá-los adequadamente; e","VIII - captar, aplicar e gerir os recursos financeiros necessários à prestação do serviço.","IX - (VETADO na Lei nº 13.448, de 5/6/2017)","Parágrafo único. As contratações, inclusive de mão-de-obra, feitas pela concessionária serão regidas pelas disposições de direito privado e pela legislação trabalhista, não se estabelecendo qualquer relação entre os terceiros contratados pela concessionária e o poder concedente."],"url":""},{"key":"l8987:32","law":"l8987","ref":"32","label":"Lei de Concessões e Permissões · Art. 32","paragraphs":["Art. 32. O poder concedente poderá intervir na concessão, com o fim de assegurar a adequação na prestação do serviço, bem como o fiel cumprimento das normas contratuais, regulamentares e legais pertinentes.","Parágrafo único. A intervenção far-se-á por decreto do poder concedente, que conterá a designação do interventor, o prazo da intervenção e os objetivos e limites da medida."],"url":""},{"key":"l8987:33","law":"l8987","ref":"33","label":"Lei de Concessões e Permissões · Art. 33","paragraphs":["Art. 33. Declarada a intervenção, o poder concedente deverá, no prazo de trinta dias, instaurar procedimento administrativo para comprovar as causas determinantes da medida e apurar responsabilidades, assegurado o direito de ampla defesa.","§ 1º Se ficar comprovado que a intervenção não observou os pressupostos legais e regulamentares será declarada sua nulidade, devendo o serviço ser imediatamente devolvido à concessionária, sem prejuízo de seu direito à indenização.","§ 2º O procedimento administrativo a que se refere o caput deste artigo deverá ser concluído no prazo de até cento e oitenta dias, sob pena de considerar-se inválida a intervenção."],"url":""},{"key":"l8987:34","law":"l8987","ref":"34","label":"Lei de Concessões e Permissões · Art. 34","paragraphs":["Art. 34. Cessada a intervenção, se não for extinta a concessão, a administração do serviço será devolvida à concessionária, precedida de prestação de contas pelo interventor, que responderá pelos atos praticados durante a sua gestão."],"url":""},{"key":"l8987:35","law":"l8987","ref":"35","label":"Lei de Concessões e Permissões · Art. 35","paragraphs":["Art. 35. Extingue-se a concessão por:","I - advento do termo contratual;","II - encampação;","III - caducidade;","IV - rescisão;","V - anulação; e","VI - falência ou extinção da empresa concessionária e falecimento ou incapacidade do titular, no caso de empresa individual.","§ 1º Extinta a concessão, retornam ao poder concedente todos os bens reversíveis, direitos e privilégios transferidos ao concessionário conforme previsto no edital e estabelecido no contrato.","§ 2º Extinta a concessão, haverá a imediata assunção do serviço pelo poder concedente, procedendo-se aos levantamentos, avaliações e liquidações necessários.","§ 3º A assunção do serviço autoriza a ocupação das instalações e a utilização, pelo poder concedente, de todos os bens reversíveis.","§ 4º Nos casos previstos nos incisos I e II deste artigo, o poder concedente, antecipando-se à extinção da concessão, procederá aos levantamentos e avaliações necessários à determinação dos montantes da indenização que será devida à concessionária, na forma dos arts. 36 e 37 desta Lei."],"url":""},{"key":"l8987:36","law":"l8987","ref":"36","label":"Lei de Concessões e Permissões · Art. 36","paragraphs":["Art. 36. A reversão no advento do termo contratual far-se-á com a indenização das parcelas dos investimentos vinculados a bens reversíveis, ainda não amortizados ou depreciados, que tenham sido realizados com o objetivo de garantir a continuidade e atualidade do serviço concedido."],"url":""},{"key":"l8987:37","law":"l8987","ref":"37","label":"Lei de Concessões e Permissões · Art. 37","paragraphs":["Art. 37. Considera-se encampação a retomada do serviço pelo poder concedente durante o prazo da concessão, por motivo de interesse público, mediante lei autorizativa específica e após prévio pagamento da indenização, na forma do artigo anterior."],"url":""},{"key":"l8987:38","law":"l8987","ref":"38","label":"Lei de Concessões e Permissões · Art. 38","paragraphs":["Art. 38. A inexecução total ou parcial do contrato acarretará, a critério do poder concedente, a declaração de caducidade da concessão ou a aplicação das sanções contratuais, respeitadas as disposições deste artigo, do art. 27, e as normas convencionadas entre as partes.","§ 1º A caducidade da concessão poderá ser declarada pelo poder concedente quando:","I - o serviço estiver sendo prestado de forma inadequada ou deficiente, tendo por base as normas, critérios, indicadores e parâmetros definidores da qualidade do serviço;","II - a concessionária descumprir cláusulas contratuais ou disposições legais ou regulamentares concernentes à concessão;","III - a concessionária paralisar o serviço ou concorrer para tanto, ressalvadas as hipóteses decorrentes de caso fortuito ou força maior;","IV - a concessionária perder as condições econômicas, técnicas ou operacionais para manter a adequada prestação do serviço concedido;","V - a concessionária não cumprir as penalidades impostas por infrações, nos devidos prazos;","VI - a concessionária não atender a intimação do poder concedente no sentido de regularizar a prestação do serviço; e","VII - a concessionária não atender a intimação do poder concedente para, em 180 (cento e oitenta) dias, apresentar a documentação relativa a regularidade fiscal, no curso da concessão, na forma do art. 29 da Lei nº 8.666, de 21 de junho de 1993 . (Inciso com redação dada pela Medida Provisória nº 577, de 29/8/2012 , convertida na Lei nº 12.767, de 27/12/2012)","§ 2º A declaração da caducidade da concessão deverá ser precedida da verificação da inadimplência da concessionária em processo administrativo, assegurado o direito de ampla defesa.","§ 3º Não será instaurado processo administrativo de inadimplência antes de comunicados à concessionária, detalhadamente, os descumprimentos contratuais referidos no § 1º deste artigo, dando-lhe um prazo para corrigir as falhas e transgressões apontadas e para o enquadramento, nos termos contratuais.","§ 4º Instaurado o processo administrativo e comprovada a inadimplência, a caducidade será declarada por decreto do poder concedente, independentemente de indenização prévia, calculada no decurso do processo.","§ 5º A indenização de que trata o parágrafo anterior, será devida na forma do art. 36 desta Lei e do contrato, descontado o valor das multas contratuais e dos danos causados pela concessionária.","§ 6º Declarada a caducidade, não resultará para o poder concedente qualquer espécie de responsabilidade em relação aos encargos, ônus, obrigações ou compromissos com terceiros ou com empregados da concessionária."],"url":""},{"key":"l9074:31","law":"l9074","ref":"31","label":"Lei 9.074/1995 · Art. 31","paragraphs":["Art. 31. Nas licitações para concessão e permissão de serviços públicos ou uso de bem público, os autores ou responsáveis economicamente pelos projetos básico ou executivo podem participar, direta ou indiretamente, da licitação ou da execução de obras ou serviços."],"url":""},{"key":"l11079:5","law":"l11079","ref":"5","label":"Lei das Parcerias Público-Privadas · Art. 5","paragraphs":["Art. 5º As cláusulas dos contratos de parceria público-privada atenderão ao disposto no art. 23 da Lei nº 8.987, de 13 de fevereiro de 1995, no que couber, devendo também prever:","I - o prazo de vigência do contrato, compatível com a amortização dos investimentos realizados, não inferior a 5 (cinco), nem superior a 35 (trinta e cinco) anos, incluindo eventual prorrogação;","II - as penalidades aplicáveis à Administração Pública e ao parceiro privado em caso de inadimplemento contratual, fixadas sempre de forma proporcional à gravidade da falta cometida, e às obrigações assumidas;","III - a repartição de riscos entre as partes, inclusive os referentes a caso fortuito, força maior, fato do príncipe e álea econômica extraordinária;","IV - as formas de remuneração e de atualização dos valores contratuais;","V - os mecanismos para a preservação da atualidade da prestação dos serviços;","VI - os fatos que caracterizem a inadimplência pecuniária do parceiro público, os modos e o prazo de regularização e, quando houver, a forma de acionamento da garantia;","VII - os critérios objetivos de avaliação do desempenho do parceiro privado;","VIII - a prestação, pelo parceiro privado, de garantias de execução suficientes e compatíveis com os ônus e riscos envolvidos, observados os limites dos §§ 3º e 5º do art. 56 da Lei nº 8.666, de 21 de junho de 1993, e, no que se refere às concessões patrocinadas, o disposto no inciso XV do art. 18 da Lei nº 8.987, de 13 de fevereiro de 1995;","IX - o compartilhamento com a Administração Pública de ganhos econômicos efetivos do parceiro privado decorrentes da redução do risco de crédito dos financiamentos utilizados pelo parceiro privado;","X - a realização de vistoria dos bens reversíveis, podendo o parceiro público reter os pagamentos ao parceiro privado, no valor necessário para reparar as irregularidades eventualmente detectadas.","XI - o cronograma e os marcos para o repasse ao parceiro privado das parcelas do aporte de recursos, na fase de investimentos do projeto e/ou após a disponibilização dos serviços, sempre que verificada a hipótese do § 2 º do art. 6 º desta Lei. (Inciso acrescido pela Lei nº 12.766, de 27/12/2012)","§ 1º As cláusulas contratuais de atualização automática de valores baseadas em índices e fórmulas matemáticas, quando houver, serão aplicadas sem necessidade de homologação pela Administração Pública, exceto se esta publicar, na imprensa oficial, onde houver, até o prazo de 15 (quinze) dias após apresentação da fatura, razões fundamentadas nesta Lei ou no contrato para a rejeição da atualização.","§ 2º Os contratos poderão prever adicionalmente:","I - os requisitos e condições em que o parceiro público autorizará a transferência do controle ou a administração temporária da sociedade de propósito específico aos seus financiadores e garantidores com quem não mantenha vínculo societário direto, com o objetivo de promover a sua reestruturação financeira e assegurar a continuidade da prestação dos serviços, não se aplicando para este efeito o previsto no inciso I do parágrafo único do art. 27 da Lei no 8.987, de 13 de fevereiro de 1995; (Inciso com redação dada pela Lei nº 13.097, de 19/1/2015)","II - a possibilidade de emissão de empenho em nome dos financiadores do projeto em relação às obrigações pecuniárias da Administração Pública;","III - a legitimidade dos financiadores do projeto para receber indenizações por extinção antecipada do contrato, bem como pagamentos efetuados pelos fundos e empresas estatais garantidores de parcerias público-privadas."],"url":""},{"key":"l11079:11","law":"l11079","ref":"11","label":"Lei das Parcerias Público-Privadas · Art. 11","paragraphs":["Art. 11. O instrumento convocatório conterá minuta do contrato, indicará expressamente a submissão da licitação às normas desta Lei e observará, no que couber, os §§ 3º e 4º do art. 15, os arts. 18, 19 e 21 da Lei nº 8.987, de 13 de fevereiro de 1995, podendo ainda prever:","I - exigência de garantia de proposta do licitante, observado o limite do inciso III do art. 31 da Lei nº 8.666, de 21 de junho de 1993;","II - (VETADO)","III - o emprego dos mecanismos privados de resolução de disputas, inclusive a arbitragem, a ser realizada no Brasil e em língua portuguesa, nos termos da Lei nº 9.307, de 23 de setembro de 1996, para dirimir conflitos decorrentes ou relacionados ao contrato.","Parágrafo único. O edital deverá especificar, quando houver, as garantias da contraprestação do parceiro público a serem concedidas ao parceiro privado."],"url":""},{"key":"l11079:13","law":"l11079","ref":"13","label":"Lei das Parcerias Público-Privadas · Art. 13","paragraphs":["Art. 13. O edital poderá prever a inversão da ordem das fases de habilitação e julgamento, hipótese em que:","I - encerrada a fase de classificação das propostas ou o oferecimento de lances, será aberto o invólucro com os documentos de habilitação do licitante mais bem classificado, para verificação do atendimento das condições fixadas no edital;","II - verificado o atendimento das exigências do edital, o licitante será declarado vencedor;","III - inabilitado o licitante melhor classificado, serão analisados os documentos habilitatórios do licitante com a proposta classificada em 2º (segundo) lugar, e assim, sucessivamente, até que um licitante classificado atenda às condições fixadas no edital;","IV - proclamado o resultado final do certame, o objeto será adjudicado ao vencedor nas condições técnicas e econômicas por ele ofertadas."],"url":""},{"key":"l11079:12","law":"l11079","ref":"12","label":"Lei das Parcerias Público-Privadas · Art. 12","paragraphs":["Art. 12. O certame para a contratação de parcerias público-privadas obedecerá ao procedimento previsto na legislação vigente sobre licitações e contratos administrativos e também ao seguinte:","I - o julgamento poderá ser precedido de etapa de qualificação de propostas técnicas, desclassificando-se os licitantes que não alcançarem a pontuação mínima, os quais não participarão das etapas seguintes;","II - o julgamento poderá adotar como critérios, além dos previstos nos incisos I e V do art. 15 da Lei nº 8.987, de 13 de fevereiro de 1995, os seguintes:","a) menor valor da contraprestação a ser paga pela Administração Pública;","b) melhor proposta em razão da combinação do critério da alínea a com o de melhor técnica, de acordo com os pesos estabelecidos no edital;","III - o edital definirá a forma de apresentação das propostas econômicas, admitindo-se:","a) propostas escritas em envelopes lacrados; ou","b) propostas escritas, seguidas de lances em viva voz;","IV - o edital poderá prever a possibilidade de saneamento de falhas, de complementação de insuficiências ou ainda de correções de caráter formal no curso do procedimento, desde que o licitante possa satisfazer as exigências dentro do prazo fixado no instrumento convocatório.","§ 1º Na hipótese da alínea b do inciso III do caput deste artigo:","I - os lances em viva voz serão sempre oferecidos na ordem inversa da classificação das propostas escritas, sendo vedado ao edital limitar a quantidade de lances;","II - o edital poderá restringir a apresentação de lances em viva voz aos licitantes cuja proposta escrita for no máximo 20% (vinte por cento) maior que o valor da melhor proposta.","§ 2º O exame de propostas técnicas, para fins de qualificação ou julgamento, será feito por ato motivado, com base em exigências, parâmetros e indicadores de resultado pertinentes ao objeto, definidos com clareza e objetividade no edital."],"url":""},{"key":"l11079:15","law":"l11079","ref":"15","label":"Lei das Parcerias Público-Privadas · Art. 15","paragraphs":["Art. 15. Compete aos Ministérios e às Agências Reguladoras, nas suas respectivas áreas de competência, submeter o edital de licitação ao órgão gestor, proceder à licitação, acompanhar e fiscalizar os contratos de parceria público-privada.","Parágrafo único. Os Ministérios e Agências Reguladoras encaminharão ao órgão a que se refere o caput do art. 14 desta Lei, com periodicidade semestral, relatórios circunstanciados acerca da execução dos contratos de parceria público-privada, na forma definida em regulamento."],"url":""},{"key":"l11079:7","law":"l11079","ref":"7","label":"Lei das Parcerias Público-Privadas · Art. 7","paragraphs":["Art. 7º A contraprestação da Administração Pública será obrigatoriamente precedida da disponibilização do serviço objeto do contrato de parceria público-privada.","§ 1º É facultado à administração p ública, nos termos do contrato, efetuar o pagamento da contraprestação relativa a parcela fruível do serviço objeto do contrato de parceria público - privada. (Parágrafo único transformado em § 1º com redação dada pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 2º O aporte de recursos de que trata o § 2º do art. 6º, quando realizado durante a fase dos investimentos a cargo do parceiro privado, deverá guardar proporcionalidade com as etapas efetivamente executadas. (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )"],"url":""},{"key":"l11079:8","law":"l11079","ref":"8","label":"Lei das Parcerias Público-Privadas · Art. 8","paragraphs":["Art. 8º As obrigações pecuniárias contraídas pela Administração Pública em contrato de parceria público-privada poderão ser garantidas mediante:","I - vinculação de receitas, observado o disposto no inciso IV do art. 167 da Constituição Federal;","II - instituição ou utilização de fundos especiais previstos em lei;","III - contratação de seguro-garantia com as companhias seguradoras que não sejam controladas pelo Poder Público;","IV - garantia prestada por organismos internacionais ou instituições financeiras; (Inciso com redação dada pela Lei nº 14.227, de 20/10/2021)","V - garantias prestadas por fundo garantidor ou empresa estatal criada para essa finalidade;","VI - outros mecanismos admitidos em lei.","Parágrafo único. ( VETADO na Lei nº 13.043, de 13/11/2014)"],"url":""},{"key":"cf:167","law":"cf","ref":"167","label":"Constituição Federal · CF/88 · Art. 167","paragraphs":["Art. 167. São vedados:","I - o início de programas ou projetos não incluídos na lei orçamentária anual;","II - a realização de despesas ou a assunção de obrigações diretas que excedam os créditos orçamentários ou adicionais;","III - a realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta;","IV - a vinculação de receita de impostos a órgão, fundo ou despesa, ressalvadas a repartição do produto da arrecadação dos impostos a que se referem os arts. 158 e 159, a destinação de recursos para as ações e serviços públicos de saúde, para manutenção e desenvolvimento do ensino e para realização de atividades da administração tributária, como determinado, respectivamente, pelos arts. 198, § 2º, 212 e 37, XXII, e a prestação de garantias às operações de crédito por antecipação de receita, previstas no art. 165, § 8º, bem como o disposto no § 4º deste artigo; (Inciso com redação dada pela Emenda Constitucional nº 42, de 2003)","V - a abertura de crédito suplementar ou especial sem prévia autorização legislativa e sem indicação dos recursos correspondentes;","VI - a transposição, o remanejamento ou a transferência de recursos de uma categoria de programação para outra ou de um órgão para outro, sem prévia autorização legislativa;","VII - a concessão ou utilização de créditos ilimitados;","VIII - a utilização, sem autorização legislativa específica, de recursos dos orçamentos fiscal e da seguridade social para suprir necessidade ou cobrir déficit de empresas, fundações e fundos, inclusive dos mencionados no art. 165, 5º;","IX - a instituição de fundos de qualquer natureza, sem prévia autorização legislativa.","X - a transferência voluntária de recursos e a concessão de empréstimos, inclusive por antecipação de receita, pelos Governos Federal e Estaduais e suas instituições financeiras, para pagamento de despesas com pessoal ativo, inativo e pensionista, dos Estados, do Distrito Federal e dos Municípios. (Inciso acrescido pela Emenda Constitucional nº 19, de 1998)","XI - a utilização dos recursos provenientes das contribuições sociais de que trata o art. 195, I, a, e II, para a realização de despesas distintas do pagamento de benefícios do regime geral de previdência social de que trata o art. 201. (Inciso acrescido pela Emenda Constitucional nº 20, de 1998)","XII - na forma estabelecida na lei complementar de que trata o § 22 do art. 40, a utilização de recursos de regime próprio de previdência social, incluídos os valores integrantes dos fundos previstos no art. 249, para a realização de despesas distintas do pagamento dos benefícios previdenciários do respectivo fundo vinculado àquele regime e das despesas necessárias à sua organização e ao seu funcionamento; (Inciso acrescido pela Emenda Constitucional nº 103, de 2019)","XIII - a transferência voluntária de recursos, a concessão de avais, as garantias e as subvenções pela União e a concessão de empréstimos e de financiamentos por instituições financeiras federais aos Estados, ao Distrito Federal e aos Municípios na hipótese de descumprimento das regras gerais de organização e de funcionamento de regime próprio de previdência social; (Inciso acrescido pela Emenda Constitucional nº 103, de 2019)","XIV - a criação de fundo público, quando seus objetivos puderem ser alcançados mediante a vinculação de receitas orçamentárias específicas ou mediante a execução direta por programação orçamentária e financeira de órgão ou entidade da administração pública. (Inciso acrescido pela Emenda Constitucional nº 109, de 2021)","§ 1º Nenhum investimento cuja execução ultrapasse um exercício financeiro poderá ser iniciado sem prévia inclusão no plano plurianual, ou sem lei que autorize a inclusão, sob pena de crime de responsabilidade.","§ 2º Os créditos especiais e extraordinários terão vigência no exercício financeiro em que forem autorizados, salvo se o ato de autorização for promulgado nos últimos quatro meses daquele exercício, caso em que, reabertos nos limites de seus saldos, serão incorporados ao orçamento do exercício financeiro subseqüente.","§ 3º A abertura de crédito extraordinário somente será admitida para atender a despesas imprevisíveis e urgentes, como as decorrentes de guerra, comoção interna ou calamidade pública, observado o disposto no art. 62.","§ 4º É permitida a vinculação das receitas a que se referem os arts. 155, 156, 156-A, 157, 158 e as alíneas \"a\", \"b\", \"d\", \"e\" e \"f\" do inciso I e o inciso II do caput do art. 159 desta Constituição para pagamento de débitos com a União e para prestar-lhe garantia ou contragarantia. (Parágrafo acrescido pela Emenda Constitucional nº 3, de 1993, e com nova redação dada pela Emenda Constitucional nº 132, de 2023)","§ 5º A transposição, o remanejamento ou a transferência de recursos de uma categoria de programação para outra poderão ser admitidos, no âmbito das atividades de ciência, tecnologia e inovação, com o objetivo de viabilizar os resultados de projetos restritos a essas funções, mediante ato do Poder Executivo, sem necessidade da prévia autorização legislativa prevista no inciso VI deste artigo. (Parágrafo acrescido pela Emenda Constitucional nº 85, de 2015, republicada no DOU de 3/3/2015)","§ 6º Para fins da apuração ao término do exercício financeiro do cumprimento do limite de que trata o inciso III do caput deste artigo, as receitas das operações de crédito efetuadas no contexto da gestão da dívida pública mobiliária federal somente serão consideradas no exercício financeiro em que for realizada a respectiva despesa. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 7º A lei não imporá nem transferirá qualquer encargo financeiro decorrente da prestação de serviço público, inclusive despesas de pessoal e seus encargos, para a União, os Estados, o Distrito Federal ou os Municípios, sem a previsão de fonte orçamentária e financeira necessária à realização da despesa ou sem a previsão da correspondente transferência de recursos financeiros necessários ao seu custeio, ressalvadas as obrigações assumidas espontaneamente pelos entes federados e aquelas decorrentes da fixação do salário mínimo, na forma do inciso IV do caput do art. 7º desta Constituição. (Parágrafo acrescido pela Emenda Constitucional nº 128, de 2022)"],"url":""},{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal · CF/88 · Art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":""},{"key":"l11079:16","law":"l11079","ref":"16","label":"Lei das Parcerias Público-Privadas · Art. 16","paragraphs":["Art. 16. Ficam a União, seus fundos especiais, suas autarquias, suas fundações públicas e suas empresas estatais dependentes autorizadas a participar, no limite global de R$ 6.000.000.000,00 (seis bilhões de reais), em Fundo Garantidor de Parcerias Público-Privadas - FGP que terá por finalidade prestar garantia de pagamento de obrigações pecuniárias assumidas pelos parceiros públicos federais, distritais, estaduais ou municipais em virtude das parcerias de que trata esta Lei . (“ Caput ” do artigo com redação dada pela Lei nº 12.766, de 27/12/2012)","§ 1º O FGP terá natureza privada e patrimônio próprio separado do patrimônio dos cotistas, e será sujeito a direitos e obrigações próprios.","§ 2º O patrimônio do Fundo será formado pelo aporte de bens e direitos realizado pelos cotistas, por meio da integralização de cotas e pelos rendimentos obtidos com sua administração.","§ 3º Os bens e direitos transferidos ao Fundo serão avaliados por empresa especializada, que deverá apresentar laudo fundamentado, com indicação dos critérios de avaliação adotados e instruído com os documentos relativos aos bens avaliados.","§ 4º A integralização das cotas poderá ser realizada em dinheiro, títulos da dívida pública, bens imóveis dominicais, bens móveis, inclusive ações de sociedade de economia mista federal excedentes ao necessário para manutenção de seu controle pela União, ou outros direitos com valor patrimonial.","§ 5º O FGP responderá por suas obrigações com os bens e direitos integrantes de seu patrimônio, não respondendo os cotistas por qualquer obrigação do Fundo, salvo pela integralização das cotas que subscreverem.","§ 6º A integralização com bens a que se refere o § 4º deste artigo será feita independentemente de licitação, mediante prévia avaliação e autorização específica do Presidente da República, por proposta do Ministro da Fazenda.","§ 7º O aporte de bens de uso especial ou de uso comum no FGP será condicionado a sua desafetação de forma individualizada.","§ 8º A capitalização do FGP, quando realizada por meio de recursos orçamentários, dar-se-á por ação orçamentária específica para esta finalidade, no âmbito de Encargos Financeiros da União . (Parágrafo acrescido pela Medida Provisória nº 513, de 26/11/2010 , convertida na Lei nº 12.409, de 25/5/2011 )","§ 9 º (VETADO na Lei nº 12.766, de 27/12/2012)"],"url":""},{"key":"l11079:21","law":"l11079","ref":"21","label":"Lei das Parcerias Público-Privadas · Art. 21","paragraphs":["Art. 21. É facultada a constituição de patrimônio de afetação que não se comunicará com o restante do patrimônio do FGP, ficando vinculado exclusivamente à garantia em virtude da qual tiver sido constituído, não podendo ser objeto de penhora, arresto, sequestro, busca e apreensão ou qualquer ato de constrição judicial decorrente de outras obrigações do FGP.","Parágrafo único. A constituição do patrimônio de afetação será feita por registro em Cartório de Registro de Títulos e Documentos ou, no caso de bem imóvel, no Cartório de Registro Imobiliário correspondente."],"url":""},{"key":"l11079:17","law":"l11079","ref":"17","label":"Lei das Parcerias Público-Privadas · Art. 17","paragraphs":["Art. 17. O FGP será criado, administrado, gerido e representado judicial e extrajudicialmente por instituição financeira controlada, direta ou indiretamente, pela União, com observância das normas a que se refere o inciso XXII do art. 4º da Lei nº 4.595, de 31 de dezembro de 1964.","§ 1º O estatuto e o regulamento do FGP serão aprovados em assembléia dos cotistas.","§ 2º A representação da União na assembléia dos cotistas dar-se-á na forma do inciso V do art. 10 do Decreto-Lei nº 147, de 3 de fevereiro de 1967.","§ 3º Caberá à instituição financeira deliberar sobre a gestão e alienação dos bens e direitos do FGP, zelando pela manutenção de sua rentabilidade e liquidez."],"url":""},{"key":"l11079:18","law":"l11079","ref":"18","label":"Lei das Parcerias Público-Privadas · Art. 18","paragraphs":["Art. 18. O estatuto e o regulamento do FGP devem deliberar sobre a política de concessão de garantias, inclusive no que se refere à relação entre ativos e passivos do Fundo . (“ Caput ” do artigo com redação dada pela Medida Provisória nº 513, de 26/11/2010 , convertida na Lei nº 12.409, de 25/5/2011 )","§ 1º A garantia será prestada na forma aprovada pela assembléia dos cotistas, nas seguintes modalidades:","I - fiança, sem benefício de ordem para o fiador;","II - penhor de bens móveis ou de direitos integrantes do patrimônio do FGP, sem transferência da posse da coisa empenhada antes da execução da garantia;","III - hipoteca de bens imóveis do patrimônio do FGP;","IV - alienação fiduciária, permanecendo a posse direta dos bens com o FGP ou com agente fiduciário por ele contratado antes da execução da garantia;","V - outros contratos que produzam efeito de garantia, desde que não transfiram a titularidade ou posse direta dos bens ao parceiro privado antes da execução da garantia;","VI - garantia, real ou pessoal, vinculada a um patrimônio de afetação constituído em decorrência da separação de bens e direitos pertencentes ao FGP.","§ 2º O FGP poderá prestar contra-garantias a seguradoras, instituições financeiras e organismos internacionais que garantirem o cumprimento das obrigações pecuniárias dos cotistas em contratos de parceria público-privadas.","§ 3º A quitação pelo parceiro público de cada parcela de débito garantido pelo FGP importará exoneração proporcional da garantia.","§ 4º O FGP poderá prestar garantia mediante contratação de instrumentos disponíveis em mercado, inclusive para complementação das modalidades previstas no § 1º. (Parágrafo com redação dada pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 5º O parceiro privado poderá acionar o FGP nos casos de:","I - crédito líquido e certo, constante de título exigível aceito e não pago pelo parceiro público após 15 ( quinze ) dias contados da data de vencimento; e","II - débitos constantes de faturas emitidas e não aceitas pelo parceiro público após 45 ( quarenta e cinco ) dias contados da data de vencimento, desde que não tenha havido rejeição expressa por ato motivado. (Parágrafo com redação dada pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012)","§ 6º A quitação de débito pelo FGP importará sua subrogação nos direitos do parceiro privado.","§ 7º Em caso de inadimplemento, os bens e direitos do Fundo poderão ser objeto de constrição judicial e alienação para satisfazer as obrigações garantidas.","§ 8º O FGP poderá usar parcela da cota da União para prestar garantia aos seus fundos especiais, às suas autarquias, às suas fundações públicas e às suas empresas estatais dependentes . (Parágrafo acrescido pela Medida Provisória nº 513, de 26/11/2010 , convertida na Lei nº 12.409, de 25/5/2011 )","§ 9º O FGP é obrigado a honrar faturas aceitas e não pagas pelo parceiro público. (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 10. O FGP é proibido de pagar faturas rejeitadas expressamente por ato motivado. (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 11. O parceiro público deverá informar o FGP sobre qualquer fatura rejeitada e sobre os motivos da rejeição no prazo de 40 ( quarenta ) dias contado da data de vencimento. (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 12. A ausência de aceite ou rejeição expressa de fatura por parte do parceiro público no prazo de 40 ( quarenta ) dias contado da data de vencimento implicará aceitação tácita. (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 13. O agente público que contribuir por ação ou omissão para a aceitação tácita de que trata o §12 ou que rejeitar fatura sem motivação será responsabilizado pelos danos que causar, em conformidade com a legislação civil, administrativa e penal em vigor. (Parágrafo acrescido pela Medida Provisória nº 575, de 7/8/2012 , convertida na Lei nº 12.766, de 27/12/2012 )"],"url":""},{"key":"l11079:19","law":"l11079","ref":"19","label":"Lei das Parcerias Público-Privadas · Art. 19","paragraphs":["Art. 19. O FGP não pagará rendimentos a seus cotistas, assegurando- se a qualquer deles o direito de requerer o resgate total ou parcial de suas cotas, correspondente ao patrimônio ainda não utilizado para a concessão de garantias, fazendo-se a liquidação com base na situação patrimonial do Fundo."],"url":""},{"key":"l11079:20","law":"l11079","ref":"20","label":"Lei das Parcerias Público-Privadas · Art. 20","paragraphs":["Art. 20. A dissolução do FGP, deliberada pela assembléia dos cotistas, ficará condicionada à prévia quitação da totalidade dos débitos garantidos ou liberação das garantias pelos credores.","Parágrafo único. Dissolvido o FGP, o seu patrimônio será rateado entre os cotistas, com base na situação patrimonial à data da dissolução."],"url":""},{"key":"l11079:9","law":"l11079","ref":"9","label":"Lei das Parcerias Público-Privadas · Art. 9","paragraphs":["Art. 9º Antes da celebração do contrato, deverá ser constituída sociedade de propósito específico, incumbida de implantar e gerir o objeto da parceria.","§ 1º A transferência do controle da sociedade de propósito específico estará condicionada à autorização expressa da Administração Pública, nos termos do edital e do contrato, observado o disposto no parágrafo único do art. 27 da Lei nº 8.987, de 13 de fevereiro de 1995.","§ 2º A sociedade de propósito específico poderá assumir a forma de companhia aberta, com valores mobiliários admitidos a negociação no mercado.","§ 3º A sociedade de propósito específico deverá obedecer a padrões de governança corporativa e adotar contabilidade e demonstrações financeiras padronizadas, conforme regulamento.","§ 4º Fica vedado à Administração Pública ser titular da maioria do capital votante das sociedades de que trata este Capítulo.","§ 5º A vedação prevista no § 4º deste artigo não se aplica à eventual aquisição da maioria do capital votante da sociedade de propósito específico por instituição financeira controlada pelo Poder Público em caso de inadimplemento de contratos de financiamento."],"url":""},{"key":"l11079:22","law":"l11079","ref":"22","label":"Lei das Parcerias Público-Privadas · Art. 22","paragraphs":["Art. 22. A União somente poderá contratar parceria público-privada quando a soma das despesas de caráter continuado derivadas do conjunto das parcerias já contratadas não tiver excedido, no ano anterior, a 1% (um por cento) da receita corrente líquida do exercício, e as despesas anuais dos contratos vigentes, nos 10 (dez) anos subsequentes, não excedam a 1% (um por cento) da receita corrente líquida projetada para os respectivos exercícios."],"url":""},{"key":"l11079:28","law":"l11079","ref":"28","label":"Lei das Parcerias Público-Privadas · Art. 28","paragraphs":["Art. 28. A União não poderá conceder garantia ou realizar transferência voluntária aos Estados, Distrito Federal e Municípios se a soma das despesas de caráter continuado derivadas do conjunto das parcerias já contratadas por esses entes tiver excedido, no ano anterior, a 5% ( cinco por cento ) da receita corrente líquida do exercício ou se as despesas anuais dos contratos vigentes nos 10 ( dez ) anos subsequentes excederem a 5 % ( cinco ) por cento da receita corrente líquida projetada para os respectivos exercícios . (“ Caput ” do artigo com redação dada pela Medida Provisória nº 575 , de 7/8/20 12 , convertida na Lei nº 12.766, de 27/12/2012 )","§ 1º Os Estados, o Distrito Federal e os Municípios que contratarem empreendimentos por intermédio de parcerias público-privadas deverão encaminhar ao Senado Federal e à Secretaria do Tesouro Nacional, previamente à contratação, as informações necessárias para cumprimento do previsto no caput deste artigo.","§ 2º Na aplicação do limite previsto no caput deste artigo, serão computadas as despesas derivadas de contratos de parceria celebrados pela administração pública direta, autarquias, fundações públicas, empresas públicas, sociedades de economia mista e demais entidades controladas, direta ou indiretamente, pelo respectivo ente, excluídas as empresas estatais não dependentes. (Parágrafo com redação dada pela Lei nº 12.024, de 27/8/2009)","§ 3º (VETADO)"],"url":""},{"key":"l11079:14","law":"l11079","ref":"14","label":"Lei das Parcerias Público-Privadas · Art. 14","paragraphs":["Art. 14. Será instituído, por decreto, órgão gestor de parcerias público-privadas federais, com competência para:","I - definir os serviços prioritários para execução no regime de parceria público-privada;","II - disciplinar os procedimentos para celebração desses contratos;","III - autorizar a abertura da licitação e aprovar seu edital;","IV - apreciar os relatórios de execução dos contratos.","§ 1º O órgão mencionado no caput deste artigo será composto por indicação nominal de um representante titular e respectivo suplente de cada um dos seguintes órgãos:","I - Ministério do Planejamento, Orçamento e Gestão, ao qual cumprirá a tarefa de coordenação das respectivas atividades;","II - Ministério da Fazenda;","III - Casa Civil da Presidência da República.","§ 2º Das reuniões do órgão a que se refere o caput deste artigo para examinar projetos de parceria público-privada participará um representante do órgão da Administração Pública direta cuja área de competência seja pertinente ao objeto do contrato em análise.","§ 3º Para deliberação do órgão gestor sobre a contratação de parceria público-privada, o expediente deverá estar instruído com pronunciamento prévio e fundamentado:","I - do Ministério do Planejamento, Orçamento e Gestão, sobre o mérito do projeto;","II - do Ministério da Fazenda, quanto à viabilidade da concessão da garantia e à sua forma, relativamente aos riscos para o Tesouro Nacional e ao cumprimento do limite de que trata o art. 22 desta Lei.","§ 4º Para o desempenho de suas funções, o órgão citado no caput deste artigo poderá criar estrutura de apoio técnico com a presença de representantes de instituições públicas.","§ 5º O órgão de que trata o caput deste artigo remeterá ao Congresso Nacional e ao Tribunal de Contas da União, com periodicidade anual, relatórios de desempenho dos contratos de parceria público-privada.","§ 6º Para fins do atendimento do disposto no inciso V do art. 4º desta Lei, ressalvadas as informações classificadas como sigilosas, os relatórios de que trata o § 5º deste artigo serão disponibilizados ao público, por meio de rede pública de transmissão de dados."],"url":""},{"key":"l11079:25","law":"l11079","ref":"25","label":"Lei das Parcerias Público-Privadas · Art. 25","paragraphs":["Art. 25. A Secretaria do Tesouro Nacional editará, na forma da legislação pertinente, normas gerais relativas à consolidação das contas públicas aplicáveis aos contratos de parceria público-privada."],"url":""},{"key":"l8987:2","law":"l8987","ref":"2","label":"Lei de Concessões e Permissões · Art. 2","paragraphs":["Art. 2º Para os fins do disposto nesta Lei, considera-se:","I - poder concedente: a União, o Estado, o Distrito Federal ou o Município, em cuja competência se encontre o serviço público, precedido ou não da execução de obra pública, objeto de concessão ou permissão;","II - concessão de serviço público: a delegação de sua prestação, feita pelo poder concedente, mediante licitação, na modalidade concorrência ou diálogo competitivo, a pessoa jurídica ou consórcio de empresas que demonstre capacidade para seu desempenho, por sua conta e risco e por prazo determinado; ( Inciso com redação dada pela Lei nº 14.133, de 1º/4/2021)","III - concessão de serviço público precedida da execução de obra pública: a construção, total ou parcial, conservação, reforma, ampliação ou melhoramento de quaisquer obras de interesse público, delegados pelo poder concedente, mediante licitação, na modalidade concorrência ou diálogo competitivo, a pessoa jurídica ou consórcio de empresas que demonstre capacidade para a sua realização, por sua conta e risco, de forma que o investimento da concessionária seja remunerado e amortizado mediante a exploração do serviço ou da obra por prazo determinado ; ( Inciso com redação dada pela Lei nº 14.133, de 1º/4/2021)","IV - permissão de serviço público: a delegação, a título precário, mediante licitação, da prestação de serviços públicos, feita pelo poder concedente à pessoa física ou jurídica que demonstre capacidade para seu desempenho, por sua conta e risco."],"url":""},{"key":"l8987:6","law":"l8987","ref":"6","label":"Lei de Concessões e Permissões · Art. 6","paragraphs":["Art. 6º Toda concessão ou permissão pressupõe a prestação de serviço adequado ao pleno atendimento dos usuários, conforme estabelecido nesta Lei, nas normas pertinentes e no respectivo contrato.","§ 1º Serviço adequado é o que satisfaz as condições de regularidade, continuidade, eficiência, segurança, atualidade, generalidade, cortesia na sua prestação e modicidade das tarifas.","§ 2º A atualidade compreende a modernidade das técnicas, do equipamento e das instalações e a sua conservação, bem como a melhoria e expansão do serviço.","§ 3º Não se caracteriza como descontinuidade do serviço a sua interrupção em situação de emergência ou após prévio aviso, quando:","I - motivada por razões de ordem técnica ou de segurança das instalações; e,","II - por inadimplemento do usuário, considerado o interesse da coletividade.","§ 4º A interrupção do serviço na hipótese prevista no inciso II do § 3º deste artigo não poderá iniciar-se na sexta-feira, no sábado ou no domingo, nem em feriado ou no dia anterior a feriado. (Parágrafo acrescido pela Lei nº 14.015, de 15/6/2020)"],"url":""},{"key":"l8987:9","law":"l8987","ref":"9","label":"Lei de Concessões e Permissões · Art. 9","paragraphs":["Art. 9º A tarifa do serviço público concedido será fixada pelo preço da proposta vencedora da licitação e preservada pelas regras de revisão previstas nesta Lei, no edital e no contrato.","§ 1º A tarifa não será subordinada à legislação específica anterior e somente nos casos expressamente previstos em lei, sua cobrança poderá ser condicionada à existência de serviço público alternativo e gratuito para o usuário. (Parágrafo com redação dada pela Lei nº 9.648, de 27/5/1998)","§ 2º Os contratos poderão prever mecanismos de revisão das tarifas, a fim de manter-se o equilíbrio econômico-financeiro.","§ 3º Ressalvados os impostos sobre a renda, a criação, alteração ou extinção de quaisquer tributos ou encargos legais, após a apresentação da proposta, quando comprovado seu impacto, implicará a revisão da tarifa, para mais ou para menos, conforme o caso.","§ 4º Em havendo alteração unilateral do contrato que afete o seu inicial equilíbrio econômico-financeiro, o poder concedente deverá restabelecê-lo, concomitantemente à alteração.","§ 5º A concessionária deverá divulgar em seu sítio eletrônico, de forma clara e de fácil compreensão pelos usuários, tabela com o valor das tarifas praticadas e a evolução das revisões ou reajustes realizados nos últimos cinco anos. (Parágrafo acrescido pela Lei nº 13.673, de 5/6/2018)"],"url":""},{"key":"l8987:11","law":"l8987","ref":"11","label":"Lei de Concessões e Permissões · Art. 11","paragraphs":["Art. 11. No atendimento às peculiaridades de cada serviço público, poderá o poder concedente prever, em favor da concessionária, no edital de licitação, a possibilidade de outras fontes provenientes de receitas alternativas, complementares, acessórias ou de projetos associados, com ou sem exclusividade, com vistas a favorecer a modicidade das tarifas, observado o disposto no art. 17 desta Lei.","Parágrafo único. As fontes de receita previstas neste artigo serão obrigatoriamente consideradas para a aferição do inicial equilíbrio econômico-financeiro do contrato."],"url":""},{"key":"l8987:10","law":"l8987","ref":"10","label":"Lei de Concessões e Permissões · Art. 10","paragraphs":["Art. 10. Sempre que forem atendidas as condições do contrato, considera-se mantido seu equilíbrio econômico-financeiro."],"url":""}];})(window);
